import{_ as a,o as e,c as n,a2 as s}from"./chunks/framework.RycU2wFZ.js";const g=JSON.parse('{"title":"项目概览","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/overview.md","filePath":"zh/guide/overview.md","lastUpdated":1792461198000}'),o={name:"zh/guide/overview.md"};function d(r,t,i,l,c,p){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="项目概览" tabindex="-1">项目概览 <a class="header-anchor" href="#项目概览" aria-label="Permalink to &quot;项目概览&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">实验性项目</p><p>AgentPay 仍在积极开发中，<strong>尚未</strong>经过独立第三方安全审计，仅适用于测试网与沙箱环境。请勿接入生产主网资金。</p></div><h2 id="agentpay-是什么" tabindex="-1">AgentPay 是什么？ <a class="header-anchor" href="#agentpay-是什么" aria-label="Permalink to &quot;AgentPay 是什么？&quot;">​</a></h2><p><strong>AgentPay</strong> 是一个开源的、面向 AI Agent 的<strong>金融防火墙与自主支付网关</strong>。</p><p>当 LLM Agent 通过 Tool Calling、MCP、LangChain、CrewAI 等方式调用外部工具、API 与数据源时，越来越多的资源是收费的。x402 协议回答的是&quot;Agent 如何为一个 HTTP 资源付款&quot;，而 AgentPay 回答紧随其后、也更难的问题：</p><blockquote><p><strong>这个 Agent 是否有资格付款？最多付多少？付给谁？出了问题怎么办？</strong></p></blockquote><p>核心原则很简单：<strong>LLM 可以&quot;提议&quot;付款，但永远不能&quot;批准&quot;付款。</strong> 每一笔支付在资金流动之前，都必须经过独立于模型的确定性代码，执行预算与策略校验。</p><h3 id="适合谁用" tabindex="-1">适合谁用？ <a class="header-anchor" href="#适合谁用" aria-label="Permalink to &quot;适合谁用？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>你是…</th><th>AgentPay 提供…</th></tr></thead><tbody><tr><td><strong>Agent 开发者</strong>（买方）</td><td>即插即用的 Python 客户端：自动处理 <code>HTTP 402</code>、本地执行限额、模型永远接触不到私钥。</td></tr><tr><td><strong>API / 工具提供方</strong>（卖方）</td><td>反向代理网关：通过 YAML 或控制台配置路由，即可把现有 HTTP API 变成付费 API，无需修改上游代码。</td></tr><tr><td><strong>平台 / 企业团队</strong></td><td>多租户隔离、RBAC、按 Agent 颁发 API Key、虚拟钱包、审计时间线与一键停用（Kill Switch）。</td></tr></tbody></table><hr><h2 id="解决的问题" tabindex="-1">解决的问题 <a class="header-anchor" href="#解决的问题" aria-label="Permalink to &quot;解决的问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风险</th><th>会发生什么</th><th>AgentPay 的应对</th></tr></thead><tbody><tr><td><strong>失控循环</strong></td><td>有缺陷的工具调用循环在几秒内对同一 API 反复付款数百次。</td><td>24 小时滚动预算、单笔上限、频率限制，以及可识别循环调用的<strong>熔断器</strong>。</td></tr><tr><td><strong>提示词注入与幻觉</strong></td><td>被污染的提示词诱导 Agent 向攻击者付款，或接受被抬高的价格。</td><td>收款人 / 网络 / 资产<strong>白名单</strong>与硬性 <code>max_per_tx</code> 上限，在模型之外执行。</td></tr><tr><td><strong>密钥泄露</strong></td><td>私钥或主密钥通过提示词上下文泄漏。</td><td>钱包路径：Agent 仅持有可撤销的 API Key；链上路径：私钥留在买方本地签名器 / KMS，绝不发送给网关。</td></tr><tr><td><strong>重复扣款</strong></td><td>把超时误判为失败并重试，导致买方付了两次。</td><td><strong>三态模型</strong>（意图 / 结算 / 履约）、幂等键，以及&quot;超时 ≠ 失败&quot;的硬规则。</td></tr><tr><td><strong>预算竞态</strong></td><td>并发请求同时看到&quot;预算足够&quot;，合计超支。</td><td><strong>原子预留</strong>（<code>reserve → commit / release</code>）与行级锁（<code>SELECT … FOR UPDATE</code>）。</td></tr><tr><td><strong>跨租户泄露</strong></td><td>一个客户读取或修改另一个客户的路由、密钥或资金。</td><td>租户级数据模型、服务端 RBAC，以及专门的隔离与越权渗透测试。</td></tr><tr><td><strong>Agent 失控</strong></td><td>生产环境中某个 Agent 行为异常。</td><td><strong>一键停用</strong>：暂停 Agent 或撤销其 API Key，网关数秒内阻断新请求。</td></tr></tbody></table><hr><h2 id="一笔支付是如何完成的" tabindex="-1">一笔支付是如何完成的 <a class="header-anchor" href="#一笔支付是如何完成的" aria-label="Permalink to &quot;一笔支付是如何完成的&quot;">​</a></h2><p>AgentPay 支持两条支付路径，网关根据请求携带的凭证<strong>确定性地</strong>选择其一。</p><h3 id="路径-a-—-虚拟钱包-api-key" tabindex="-1">路径 A — 虚拟钱包（API Key） <a class="header-anchor" href="#路径-a-—-虚拟钱包-api-key" aria-label="Permalink to &quot;路径 A — 虚拟钱包（API Key）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent ── HTTP + Authorization: Bearer apk_live_… ──▶ Gateway</span></span>
<span class="line"><span>   1. 校验 Key        → 解析租户、项目与 Agent</span></span>
<span class="line"><span>   2. 策略检查        → 单笔上限、预算、频率限制、路由白名单</span></span>
<span class="line"><span>   3. HOLD（冻结）    → 在租户钱包中冻结价格（行级锁）</span></span>
<span class="line"><span>   4. 转发上游（上游凭证由网关注入）</span></span>
<span class="line"><span>   5a. 2xx  → CAPTURE（确认扣款）→ 追加账本流水，返回 200</span></span>
<span class="line"><span>   5b. 4xx  → RELEASE（释放）    → 解冻，不扣费</span></span>
<span class="line"><span>   5c. 5xx / 超时 → 保持 HELD，标记 needs_review（既不自动扣费，也不自动释放）</span></span></code></pre></div><h3 id="路径-b-—-链上-x402-eip-3009" tabindex="-1">路径 B — 链上 x402（EIP-3009） <a class="header-anchor" href="#路径-b-—-链上-x402-eip-3009" aria-label="Permalink to &quot;路径 B — 链上 x402（EIP-3009）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent ── GET /resource ──▶ Gateway</span></span>
<span class="line"><span>Agent ◀── 402 + PAYMENT-REQUIRED（价格、收款人、资产、网络、有效期）──</span></span>
<span class="line"><span>   1. 客户端解析挑战</span></span>
<span class="line"><span>   2. 本地策略引擎：评估并原子地预留（RESERVE）预算</span></span>
<span class="line"><span>   3. 本地签名器：生成 EIP-712 / EIP-3009 授权签名</span></span>
<span class="line"><span>   4. 携带 PAYMENT-SIGNATURE 重放请求</span></span>
<span class="line"><span>   5. 网关校验签名、Nonce 与价格 → 转发上游</span></span>
<span class="line"><span>   6. Facilitator 上链结算（Gas 由其代付，买方只需持有 USDC）</span></span>
<span class="line"><span>   7. 买方提交（或在授权过期且确认未花费后释放）预留额度</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">禁止静默降级</p><p>钱包路径余额不足时，网关返回 <code>402 ERR_WALLET_INSUFFICIENT_BALANCE</code>，<strong>绝不</strong>悄悄改走链上扣费。改用链上支付必须是买方显式发起、并经其签名的新请求。</p></div><hr><h2 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────┐        ┌───────────────────────────────┐        ┌────────────────────┐</span></span>
<span class="line"><span>│       AI Agent       │        │        AgentPay Gateway       │        │      上游服务      │</span></span>
<span class="line"><span>│ LangChain / CrewAI / │ ─────▶ │  鉴权 · 策略 · x402 · 代理    │ ─────▶ │  （你现有的        │</span></span>
<span class="line"><span>│  自研 + SDK 客户端   │        │  钱包 Hold/Capture/Release    │        │   HTTP API）       │</span></span>
<span class="line"><span>└──────────┬───────────┘        └───────┬───────────────┬───────┘        └────────────────────┘</span></span>
<span class="line"><span>           │                            │               │</span></span>
<span class="line"><span>   本地策略引擎 /                PostgreSQL 15+     Facilitator ──▶ EVM 链</span></span>
<span class="line"><span>   本地签名器（链上路径）      （账本、配置、      （验证与结算，Arbitrum Sepolia）</span></span>
<span class="line"><span>                                 审计事件）</span></span>
<span class="line"><span>                                        ▲</span></span>
<span class="line"><span>                              管理控制台（Vue 3）</span></span>
<span class="line"><span>                              路由 · 策略 · 钱包 · Agent · 审计</span></span></code></pre></div><table tabindex="0"><thead><tr><th>组件</th><th>职责</th></tr></thead><tbody><tr><td><strong>Python SDK</strong>（<code>agentpay</code>）</td><td>透明的 <code>httpx</code> 拦截器（同步 + 异步）：识别 <code>402</code>、执行本地防火墙、签名、重放、提交或释放；内置 LangChain 付费工具封装。</td></tr><tr><td><strong>金融防火墙 / 策略引擎</strong></td><td>单笔上限、24h 滚动预算、终身限额、收款人 / 域名 / 网络白名单、频率限制、熔断器；买方侧基于 SQLite 的原子预留。</td></tr><tr><td><strong>网关</strong>（<code>gateway-go</code>）</td><td>Go 反向代理：路由匹配、402 挑战生成、签名校验、请求头清洗、上游凭证隔离、幂等、故障恢复、Agent 级策略与 Kill Switch；v0.1.0 基线同时提供 Python 参考实现。</td></tr><tr><td><strong>虚拟钱包与账本</strong></td><td>每租户一个钱包；只追加账本；Hold / Capture / Release；对账。</td></tr><tr><td><strong>Facilitator</strong></td><td>校验授权并提交由其代付 Gas 的 <code>transferWithAuthorization</code> 交易；本地运行时提供 Mock Facilitator。</td></tr><tr><td><strong>管理控制台</strong></td><td>路由与上游鉴权、配置草稿 → 校验 → 发布 → 回滚、钱包、Agent 与审计时间线。</td></tr><tr><td><strong>PostgreSQL</strong></td><td>租户、项目、路由、策略、账本、支付与审计事件的权威数据源。</td></tr></tbody></table><hr><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="租户与身份" tabindex="-1">租户与身份 <a class="header-anchor" href="#租户与身份" aria-label="Permalink to &quot;租户与身份&quot;">​</a></h3><p><code>Tenant → Project → Agent → API Key</code>。每个项目归属唯一租户，每个 API Key 归属唯一 Agent，且 <strong><code>agent_id</code> 始终由凭证解析得出</strong>——客户端传入的 <code>X-Agent-ID</code> 等请求头会被剥离，绝不信任。可选的自报元数据（<code>X-Session-ID</code>、<code>X-Task-ID</code>、<code>X-Tool-Name</code>）仅用于审计时间线聚合，不参与鉴权、计费与策略判定。</p><h3 id="三态模型" tabindex="-1">三态模型 <a class="header-anchor" href="#三态模型" aria-label="Permalink to &quot;三态模型&quot;">​</a></h3><p>单一的&quot;支付成功 / 失败&quot;标记无法描述真实情况。AgentPay 维护三条相互正交的状态线：</p><table tabindex="0"><thead><tr><th>对象</th><th>回答的问题</th><th>示例状态</th></tr></thead><tbody><tr><td><strong>PaymentIntent（支付意图）</strong></td><td>这次请求处于整体生命周期的哪一步？</td><td><code>created</code>、<code>challenged</code>、<code>authorized</code>、<code>completed</code>、<code>rejected</code>、<code>expired</code>、<code>failed</code>、<code>needs_review</code></td></tr><tr><td><strong>Settlement（结算）</strong></td><td>钱是否真的动了？</td><td><code>not_started</code>、<code>held</code>、<code>submitted</code>、<code>pending</code>、<code>confirmed</code>、<code>released</code>、<code>failed</code>、<code>unknown</code></td></tr><tr><td><strong>Fulfillment（履约）</strong></td><td>上游是否真的交付了？</td><td><code>not_started</code>、<code>in_progress</code>、<code>succeeded</code>、<code>failed</code>、<code>unknown</code></td></tr></tbody></table><p><code>unknown</code> 是一等状态：结果不明确时，既不视为成功，也不视为失败，只能通过查询确认，严禁盲目重试。详见<a href="/docs/zh/specs/state-machine">状态机规范</a>。</p><h3 id="幂等" tabindex="-1">幂等 <a class="header-anchor" href="#幂等" aria-label="Permalink to &quot;幂等&quot;">​</a></h3><p>客户端携带 <code>Idempotency-Key</code>。相同 Key 且请求指纹一致时，直接回放已存结果（<code>X-Cache: HIT</code>），<strong>零额外扣费</strong>；相同 Key 但载荷不同则返回 <code>409 ERR_IDEMPOTENCY_CONFLICT</code>。上游 5xx 后使用相同 Key 重试，会复用原冻结，不会再次扣款。</p><h3 id="版本化配置" tabindex="-1">版本化配置 <a class="header-anchor" href="#版本化配置" aria-label="Permalink to &quot;版本化配置&quot;">​</a></h3><p>路由与策略以草稿形式编辑、校验，再发布为<strong>不可变、带哈希指纹的快照</strong>。网关零停机原子切换到新快照；每个请求都会记录其命中的配置版本；回滚只是一次指针切换。控制面宕机时，网关继续使用最近一次可用快照提供服务，对无法校验的请求一律拒绝（fail-closed）。</p><hr><h2 id="安全不变量" tabindex="-1">安全不变量 <a class="header-anchor" href="#安全不变量" aria-label="Permalink to &quot;安全不变量&quot;">​</a></h2><p>以下规则不是可调参数，而是在代码、数据库与测试中强制执行的设计约束。</p><ol><li><strong>只用整数表示金额。</strong> 所有金额均为最小单位整数（USDC 为 6 位小数），任何地方禁止浮点数，数据库列带整数 / 非负 <code>CHECK</code> 约束。</li><li><strong>默认拒绝（Fail-Closed）。</strong> 锁超时、解析错误、验签失败或任何未捕获异常 ⇒ 拒绝。</li><li><strong>批准后才签名。</strong> 只有策略引擎已批准的预留才会调用签名器。</li><li><strong>已发出的签名不会因超时而&quot;视为未花费&quot;。</strong> 只有授权过期<strong>且</strong>链上确认未花费后，才会释放预算。</li><li><strong>未知状态绝不自动处置。</strong> 履约未知时钱包资金保持冻结，并转入 <code>needs_review</code>。</li><li><strong>账本只追加。</strong> 账本流水与审计事件永不更新、删除；更正通过新增冲正 / 调账流水完成。</li><li><strong>模型没有资金权限。</strong> 策略引擎不是 LLM 工具，LLM 无法读取或修改它。</li></ol><hr><h2 id="部署拓扑" tabindex="-1">部署拓扑 <a class="header-anchor" href="#部署拓扑" aria-label="Permalink to &quot;部署拓扑&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>本地嵌入式沙箱</th><th>云原生分布式</th></tr></thead><tbody><tr><td><strong>用途</strong></td><td>开发、CI、演示（<code>make demo</code>）</td><td>真实测试网集成</td></tr><tr><td><strong>传输</strong></td><td>内存 ASGI 传输（不占用端口）</td><td>买卖双方独立域之间的 HTTPS</td></tr><tr><td><strong>链</strong></td><td>本地 Mock EVM RPC</td><td>Arbitrum Sepolia（<code>eip155:421614</code>）</td></tr><tr><td><strong>密钥</strong></td><td>测试密钥</td><td>买方本地签名器 / KMS，绝不上传</td></tr><tr><td><strong>Gas</strong></td><td>模拟</td><td>由 Facilitator 代付，买方仅持有 USDC</td></tr></tbody></table><p>详见<a href="/docs/zh/guide/deployment">部署指南</a>。</p><hr><h2 id="范围与已知限制" tabindex="-1">范围与已知限制 <a class="header-anchor" href="#范围与已知限制" aria-label="Permalink to &quot;范围与已知限制&quot;">​</a></h2><p>AgentPay 明确声明<strong>不做</strong>什么：</p><ul><li><strong>v1 不支持提现。</strong> 虚拟钱包是闭环消费余额，不支持提现与用户间转账。</li><li><strong>不做语义质量判断。</strong> AgentPay 验证的是&quot;付费调用已交付&quot;，而非&quot;答案是否有价值&quot;。在预算内向白名单 API 花了钱却得到无用结果，不在防护范围内。</li><li><strong>宿主机失陷不在范围内。</strong> 攻击者若取得运行本地签名器的机器 root 权限，可读取私钥；HSM / KMS 签名器已在规划中。</li><li><strong>进程内工具不做沙箱隔离。</strong> 嵌入模式下 SDK 与 Agent 共享进程，具备任意代码执行能力的工具可能绕过拦截器；独立进程 Sidecar 已在规划中。</li><li><strong>一个密钥对应一个本地账本。</strong> 同一私钥在多个进程中使用各自独立的账本，会使预算成倍放大。</li><li><strong>单一资产，仅限测试网。</strong> v1 仅支持一种资产（兼容 EIP-3009 的 USDC），且运行于测试网。</li></ul><p>完整的防护范围请阅读<a href="/docs/zh/specs/">威胁模型</a>。</p><hr><h2 id="当前状态与路线图" tabindex="-1">当前状态与路线图 <a class="header-anchor" href="#当前状态与路线图" aria-label="Permalink to &quot;当前状态与路线图&quot;">​</a></h2><p><strong>当前已具备（v0.1.x）</strong></p><ul><li>Python SDK：<code>httpx</code> 拦截器、本地防火墙（SQLite 原子预留、熔断器）、EIP-712 / EIP-3009 签名器、LangChain 付费工具封装</li><li>Go 网关：反向代理、x402 处理、钱包路径、幂等与故障恢复、Agent 级策略、Kill Switch、审计时间线</li><li>多租户控制面：租户、项目、RBAC、Agent、API Key、钱包与管理员发放、路由与策略</li><li>管理控制台：路由与上游鉴权、配置发布与回滚、钱包、Agent、支付审计</li><li>PostgreSQL 15+ 数据模型，Python / Go 跨语言一致性测试向量</li><li>Arbitrum Sepolia 测试网结算，以及一条命令复现的<strong>失控循环 Demo</strong></li></ul><p><strong>进行中 / 下一步</strong></p><ul><li>账本对账（五重平账）、用量统计、审计保留与导出</li><li>管理操作审计与 YAML 导入 / 导出</li><li>性能基准、干净环境部署验证、试点与候选版本发布</li></ul><p><strong>路线图（2027+）</strong></p><ul><li><strong>Gas 模式 2（v0.2.0）：</strong> 动态 Gas 加价分摊，并入 USDC 金额</li><li><strong>Gas 模式 3（v0.3.0）：</strong> 批量聚合 / 状态通道结算，支持逐 token 微支付</li><li>链上充值与法币充值</li><li>TypeScript / Node.js SDK 与 Express / Fastify 中间件</li><li>Java / Spring Boot Starter</li><li>异常检测与告警（默认仅告警）</li><li>多节点分布式网关集群、KMS / HSM 签名器</li></ul><hr><h2 id="接下来读什么" tabindex="-1">接下来读什么 <a class="header-anchor" href="#接下来读什么" aria-label="Permalink to &quot;接下来读什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我想…</th><th>阅读</th></tr></thead><tbody><tr><td>五分钟跑起来</td><td><a href="/docs/zh/guide/quickstart">5 分钟快速开始</a></td></tr><tr><td>接入 Agent</td><td><a href="/docs/zh/guide/python-sdk">Python SDK</a></td></tr><tr><td>把 API 变成付费 API</td><td><a href="/docs/zh/guide/gateway">网关配置</a></td></tr><tr><td>设置花费限额</td><td><a href="/docs/zh/guide/policy">策略配置</a></td></tr><tr><td>管理租户、密钥与路由</td><td><a href="/docs/zh/guide/console">管理控制台</a></td></tr><tr><td>了解协议细节</td><td><a href="/docs/zh/guide/api-specs">API 规范</a></td></tr><tr><td>理解各项保证</td><td><a href="/docs/zh/specs/state-machine">状态机规范</a></td></tr><tr><td>部署</td><td><a href="/docs/zh/guide/deployment">部署指南</a></td></tr><tr><td>参与贡献</td><td><a href="/docs/zh/contributing/good-first-issues">Good First Issues</a></td></tr></tbody></table>`,60)])])}const u=a(o,[["render",d]]);export{g as __pageData,u as default};
